from pwn import *
import gmpy2
from Crypto.Util.number import *
import time

context.log_level = 'error'  # Reduce noise

def reconnect():
    return remote('crypto.chal.csaw.io', 32333)

def get_oracle_response(conn, ct, retry=True):
    try:
        conn.sendline(b'2')
        time.sleep(0.1)  # Small delay
        conn.recvuntil(b'input:', timeout=2)
        conn.sendline(hex(ct)[2:].encode())
        result = int(conn.recvline(timeout=2).strip().decode(), 16)
        return result & 1
    except Exception as e:
        if retry:
            # Try once more
            try:
                conn.close()
                conn = reconnect()
                return get_oracle_response(conn, ct, retry=False)
            except:
                pass
        return None

def recover_message(initial_ct, n_bits=512, chunk_size=2):
    conn = reconnect()
    k = n_bits
    ct = initial_ct

    # Initialize bounds
    lower = 0
    upper = 2**k

    try:
        for i in range(k):
            if i % 32 == 0:
                print(f"Progress: {i}/{k} bits")

            ct = (ct * pow(2, 1, upper)) % upper

            result = get_oracle_response(conn, ct)
            if result is None:
                # Try to recover
                conn = reconnect()
                result = get_oracle_response(conn, ct)
                if result is None:
                    raise Exception("Oracle failed consistently")

            # Binary search step
            mid = (lower + upper) // 2
            if result == 1:
                lower = mid
            else:
                upper = mid

    except Exception as e:
        print(f"Error during message recovery: {e}")
        return None
    finally:
        try:
            conn.close()
        except:
            pass

    # Return middle of final interval
    return (lower + upper) // 2

def recover_flag_chunk(offset, length):
    attempts = 0
    max_attempts = 5

    while attempts < max_attempts:
        try:
            conn = reconnect()

            # Get encrypted chunk
            conn.recvuntil(b'offset,len:', timeout=2)
            conn.sendline(f"{offset},{length}".encode())

            conn.recvuntil(b'encrypted flag: ', timeout=2)
            ct_hex = conn.recvline(timeout=2).strip().decode()
            ct = int(ct_hex, 16)

            print(f"[+] Got ciphertext for offset {offset}: {ct_hex[:30]}...")

            # Recover the message
            msg = recover_message(ct)
            if msg is None:
                raise Exception("Failed to recover message")

            # Try to convert to bytes and check if printable
            try:
                chunk = long_to_bytes(msg)
                if len(chunk) >= length:
                    chunk = chunk[-length:]  # Take last length bytes
                    if all(32 <= c <= 126 for c in chunk):  # Check if printable
                        return chunk
            except:
                pass

            attempts += 1

        except Exception as e:
            print(f"[-] Attempt {attempts + 1} failed: {e}")
            attempts += 1
            time.sleep(1)  # Back off
        finally:
            try:
                conn.close()
            except:
                pass

    return None

def main():
    recovered_flag = bytearray()
    chunk_size = 2
    offset = 0
    max_size = 100

    print("[*] Starting flag recovery...")

    while offset < max_size:
        print(f"\n[+] Attempting to recover chunk at offset {offset}")
        chunk = recover_flag_chunk(offset, chunk_size)

        if chunk:
            print(f"[+] Recovered chunk at offset {offset}: {chunk}")
            recovered_flag.extend(chunk)

            try:
                flag_so_far = recovered_flag.decode()
                print(f"[*] Current recovery: {flag_so_far}")

                if "flag{" in flag_so_far and "}" in flag_so_far:
                    print(f"\n[!] FOUND FLAG: {flag_so_far}")
                    break
            except:
                pass

            offset += len(chunk)
        else:
            print(f"[-] Failed to recover chunk at offset {offset}")
            offset += 1

        time.sleep(0.5)

