context.log_level = 'info'

def get_encrypted_chunk(r, offset, length):
    r.recvuntil(b'offset,len:')
    r.sendline(f"{offset},{length}".encode())
    r.recvuntil(b'encrypted flag: ')
    return int(r.recvline().strip().decode(), 16)

def oracle(r, x):
    r.recvuntil(b'input:')
    r.sendline(hex(x)[2:].encode())
    return int(r.recvline().strip().decode(), 16) & 1

class LsbOracle:
    def __init__(self, host, port):
        self.host = host
        self.port = port

    def fresh_connection(self):
        return remote(self.host, self.port)

    def recover_message(self, ct, bits=8):
        r = self.fresh_connection()
        k = bits

        lower = 0
        upper = 1 << k

        try:
            for _ in range(k):
                ct = (ct * pow(2, 1, upper)) % upper
                r.sendline(b'2')  # Choose option 2
                res = oracle(r, ct)

                mid = (lower + upper) // 2
                if res == 1:
                    lower = mid
                else:
                    upper = mid

        finally:
            r.close()

        return (lower + upper) // 2

def get_flag():
    oracle = LsbOracle('crypto.chal.csaw.io', 32333)
    flag = b''

    for offset in range(0, 100, 2):
        print(f"[*] Trying offset {offset}")
        r = oracle.fresh_connection()

        try:
