from pwn import *
from Crypto.Util.number import *
import time

context.log_level = 'info'
HOST = 'crypto.chal.csaw.io'
PORT = 32333

def query_server(choice, value, retries=3):
    for _ in range(retries):
        try:
            r = remote(HOST, PORT, timeout=5)
            r.recvuntil(b'Choice: ')
            r.sendline(str(choice).encode())

            if choice == 1:
                r.recvuntil(b'offset,len:')
                r.sendline(value.encode())
                r.recvuntil(b'encrypted flag: ')
            else:
                r.recvuntil(b'input:')
                r.sendline(value.encode())

            result = int(r.recvline().strip().decode(), 16)
            r.close()
            return result
        except Exception as e:
            if _ == retries - 1:
                raise e
            time.sleep(1)
            continue

def get_block(offset):
    return query_server(1, f"{offset},2")

def get_lsb(ct):
    return query_server(2, hex(ct)[2:]) & 1

def recover_chunk(ct):
    plaintext = 0
    for i in range(16):
        ct_modified = (ct * pow(2, i, 2**512)) % 2**512
        bit = get_lsb(ct_modified)
        plaintext |= (bit << i)
    return plaintext

def is_printable(data):
    return all(32 <= x <= 126 for x in data)

def main():
    flag = bytearray()
    offset = 0

    while offset < 100:
        try:
            print(f"\n[*] Working on offset {offset}")

            # Get encrypted block
            ct = get_block(offset)
            print(f"[+] Got ciphertext: {hex(ct)}")

            # Recover block
            pt = recover_chunk(ct)
            chunk = long_to_bytes(pt)[-2:]

            if is_printable(chunk):
                flag.extend(chunk)
                print(f"[+] Recovered: {chunk.decode()}")
                print(f"[+] Current flag: {flag.decode()}")

                if b'}' in chunk:
                    print(f"\n[!] Found flag: {flag.decode()}")
                    break

            offset += 2
            time.sleep(0.5)  # Rate limiting

        except Exception as e:
            print(f"[-] Error occurred: {str(e)}")
            time.sleep(1)
            continue

if __name__ == '__main__':
    main()

